exploreUrl:
@js:
sort=[];
push=(title,url,type)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: 1,
				layout_flexBasisPercent: type
			}
	});

$$=(uri)=>`/flei${uri}/{{page}\}/`;
[
["综合全部",""],
["玄幻小说","/xuanhuan"],
["仙侠小说","/xianxia"],
["都市小说","/dushi"],
["历史军事","/lishi"],
["游戏竞技","/youxi"],
["科幻小说","/kehuan"],
["恐怖小说","/kongbu"],
["其他类型","/qita"]
].map([title,uri]=>{
	push(title,$$(uri),0.25);
});
JSON.stringify(sort);
